query:
NODE VALUE `incoming_degree` SumAgg<INT64> = 0
TABLE `result_table` {`id` STRING, `total` INT64}

MATCH (`src`:`player`)-[`e`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`incoming_degree` += coalesce(`e`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id`, `p`.@`incoming_degree` INTO `result_table`
}

FOR `row` IN `result_table`
RETURN `row`.`id` AS `id`, `row`.`total` AS `total`
